// MIT. Source-mode and startup composition over the original accounting Store.
import {openAccountingWorkspace} from '../../stellar/scf-starforge-20261009/merchant-settlement-accounting/workspace/store.mjs';
import {accountingWorkspaceBinding,inspectAccountingWorkspaceBinding} from '../../stellar/scf-starforge-20261009/merchant-settlement-accounting/workspace/binding.mjs';
import {accountingSourceMode,inspectBuyerStartupFile,readBuyerStartup,buyerStartupView} from '../../stellar/scf-starforge-20261009/merchant-settlement-accounting/workspace/buyer-startup.mjs';

const fail=(code,message)=>Object.assign(new Error(message),{code});
const need=(ok,code,message)=>{if(!ok)throw fail(code,message);};
const copy=value=>structuredClone(value);
const merchantMaps=['recoveredSources','recoveryRequests','proofFiles','termsFiles','pricingReports','collectionInputs','statementUsageInputs','cryptoworthInputs','runbookInputs','portfolioInputs','portfolioClients','rozoSources'];
export function configuredAccountingMode(definition){
 const mode=definition.sourceMode??'merchant';
 need(mode==='merchant'||mode==='buyer','ACCOUNTING_CONFIGURATION_ERROR','Choose sourceMode merchant or buyer.');
 return mode;
}
export function validateBuyerAccountingDefinition(definition){
 if(configuredAccountingMode(definition)!=='buyer')return;
 need(['outboxDir','proofDir','termsFile'].every(key=>definition[key]===undefined),
  'ACCOUNTING_CONFIGURATION_ERROR','A buyer-only accountant retains its issued source; omit merchant outbox, proof and terms directories.');
 need(merchantMaps.every(key=>Object.keys(definition[key]??{}).length===0)&&
  !definition.bitwave&&definition.collectionHttpsProxyEnv===undefined&&definition.adjustmentHttpsProxyEnv===undefined,
  'ACCOUNTING_CONFIGURATION_ERROR','Declare buyer source, accountant-return and QuickBooks/Xero inputs for buyer mode. Merchant collection, sales, runbook and portfolio inputs retain their original merchant workspace.');
}
export function requireBuyerAccounting(definition){
 need(configuredAccountingMode(definition)==='buyer','ACCOUNTING_BUYER_MODE_REQUIRED','Choose a host-declared buyer-only accountant workspace.');
}
function briefSource(source){
 if(!source?.buyer)return copy(source);
 const {outstandingReservations=[],sourceCaptures=[],...buyer}=source.buyer;
 return {...copy(source),buyer:{...copy(buyer),outstandingReservationsCount:outstandingReservations.length,sourceCapturesCount:sourceCaptures.length}};
}
function briefStartup(value){
 if(!value)return null;
 const {path,...retained}=copy(value);
 return {...retained,source:briefSource(value.source)};
}
export function buyerAccountingCapabilities(definition){
 const mode=configuredAccountingMode(definition);
 return {sourceMode:mode,issuedBuyerStartup:mode==='buyer',
  accountant:true,qbo:true,xero:true,merchantSources:mode==='merchant',nativeRecovery:Boolean(definition.recovery)};
}
export function buyerAccountingState(workspace){
 requireBuyerAccounting({sourceMode:accountingSourceMode(workspace.state)});
 const binding=accountingWorkspaceBinding(workspace.directory,workspace.state);
 const source=buyerStartupView(workspace.directory,workspace.state);
 const records=new Map((workspace.state.accountantHandoffs??[]).map(row=>[row.id,row]));
 source.handoffs=source.handoffs.map(row=>({...row,requestSha256:records.get(row.id).requestSha256,
  sourceSha256:records.get(row.id).source.reportSha256}));
 return {schema:'stellar-forge.buyer-accounting-operation.v1',sourceMode:'buyer',
  binding:{schema:binding.schema,workspaceId:binding.workspaceId,sourcesSha256:binding.sourcesSha256,
   sourceMode:'buyer',sourceSha256:binding.sources.buyerSourceSha256,sourceBytes:binding.sources.buyerSourceBytes},
  workspaceRevision:workspace.state.revision,source:briefStartup(source)};
}
export function buyerStartupProjection(value){return briefStartup(value);}
function sourceReview(inspected,args={}){
 const {source,rows,document}=inspected,issued=document.issued;
 const offset=args.offset??0,limit=args.limit??25,view=args.view??'summary';
 const result={source:briefSource(source),sourceKind:'buyer-expense-period',sourceSha256:inspected.sha256,
  period:copy(issued.period),totals:copy(issued.totals),creditTotals:copy(issued.credit_totals??[]),
  netTotals:copy(issued.net_totals??issued.totals),
  counts:{allocationRows:rows.length,expenseRows:rows.filter(row=>row.kind==='EXPENSE').length,
   creditRows:rows.filter(row=>row.kind==='CREDIT').length,
   outstandingReservations:source.buyer.outstandingReservations.length,sourceCaptures:source.buyer.sourceCaptures.length}};
 if(view!=='summary'){
  const selected={allocations:rows,outstanding:source.buyer.outstandingReservations,captures:source.buyer.sourceCaptures}[view];
  result.page={view,total:selected.length,offset,limit,items:copy(selected.slice(offset,offset+limit))};
 }
 return result;
}
export async function previewBuyerAccountingSource(definition,path,args){
 requireBuyerAccounting(definition);
 const selected=await inspectBuyerStartupFile(path,{expectedSha256:args.sourceSha256});
 return {...sourceReview(selected.inspected,args),input:{source:args.source,bytes:selected.bytes.length,sha256:selected.sha256}};
}
export function assertBuyerInitialization(value,args){
 need(value?.source?.sha256===args.sourceSha256&&value.source.name===args.name.trim()&&value.source.actor===args.actor.trim(),
  'ACCOUNTING_BUYER_INITIALIZATION_CHANGED','This directory already retains a different named buyer initialization. Inspect its retained startup and preserve the original source, name and operator.');
 return value;
}
export async function initializeBuyerAccounting(definition,path,args){
 requireBuyerAccounting(definition);
 let binding;
 try{binding=await inspectAccountingWorkspaceBinding(definition.directory);}
 catch(error){if(error.code!=='ENOENT')throw error;}
 if(binding)need(binding.sources.sourceMode==='buyer','ACCOUNTING_SOURCE_MODE_MISMATCH','This declared buyer directory belongs to an original merchant workspace.');
 const workspace=await openAccountingWorkspace(binding?
  {directory:definition.directory,expectedWorkspaceId:binding.workspaceId,expectedSourcesSha256:binding.sourcesSha256}:
  {directory:definition.directory,buyerSourceFile:path,buyerSourceSha256:args.sourceSha256,buyerSourceName:args.name,buyerOperator:args.actor});
 try{
  const value=assertBuyerInitialization(buyerAccountingState(workspace),args);
  return {...value,recovered:Boolean(binding)};
 }finally{await workspace.close();}
}
export async function buyerAccountingOpenSettings(definition){
 requireBuyerAccounting(definition);
 let binding;
 try{binding=await inspectAccountingWorkspaceBinding(definition.directory);}
 catch(error){
  if(error.code==='ENOENT')throw fail('ACCOUNTING_BUYER_INITIALIZATION_REQUIRED','Preview a declared original source and initialize this buyer accountant before opening it.');
  throw error;
 }
 need(binding.sources.sourceMode==='buyer','ACCOUNTING_SOURCE_MODE_MISMATCH','The configured buyer alias must retain an original buyer-only accountant workspace.');
 return {directory:definition.directory,expectedWorkspaceId:binding.workspaceId,expectedSourcesSha256:binding.sourcesSha256};
}
export function requireBuyerOperation(workspace,operation,args){
 if(accountingSourceMode(workspace.state)!=='buyer')return;
 const ordinary=new Set(['merchant_accounting_status','merchant_accounting_file','merchant_accounting_file_release',
  'merchant_accounting_accountant_buyer_prepare','merchant_accounting_accountant_buyer_create','merchant_accounting_accountant',
  'merchant_accounting_accountant_rows','merchant_accounting_accountant_preview','merchant_accounting_accountant_apply']);
 need(ordinary.has(operation)||operation.startsWith('merchant_accounting_buyer_')||operation.startsWith('merchant_accounting_qbo_')||operation.startsWith('merchant_accounting_xero_'),
  'ACCOUNTING_MERCHANT_SOURCE_REQUIRED','This alias retains an issued buyer period. Use its buyer, accountant, QuickBooks, Xero and recovery operations; merchant-source operations belong to a merchant alias.');
 if(operation==='merchant_accounting_file')need(['buyer-source','accountant','qbo','xero','qbo-source-change','xero-source-change','qbo-worksheet'].includes(args.kind),
  'ACCOUNTING_MERCHANT_SOURCE_REQUIRED','Choose the retained buyer source, accountant packet, original QuickBooks worksheet/journal, Xero file or chart-change handoff for this buyer alias.');
}
export async function callBuyerAccounting(workspace,accountant,operation,args){
 const startup=await readBuyerStartup(workspace.directory,workspace.state);
 const state=buyerAccountingState(workspace),descriptor=startup.descriptor;
 if(operation==='merchant_accounting_buyer_startup')return state;
 need(args.sourceSha256===descriptor.sha256,'ACCOUNTING_BUYER_SOURCE_CHANGED','Retain the exact issued source SHA256 selected in this buyer workspace.');
 if(operation==='merchant_accounting_buyer_prepare')return {...state,...sourceReview(startup.inspected,args),handoffId:descriptor.handoffId};
 if(operation==='merchant_accounting_buyer_handoff'){
  need(args.handoffId===descriptor.handoffId,'ACCOUNTING_BUYER_HANDOFF_CHANGED','Use the original startup handoff ID returned by prepare.');
  return accountant.create({id:descriptor.handoffId,revision:args.revision,name:args.name,actor:args.actor,
   labels:[],buyerStartup:{sha256:descriptor.sha256}});
 }
 throw fail('ACCOUNTING_UNKNOWN_TOOL','Unknown original buyer-accountant operation.');
}

// MIT. Accounting maintenance through the merchant's existing MCP connection.
import { createHash } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import { openMerchantFileClient } from './retained-download.mjs';
import { qboWorksheetFileSelectors } from './catalog/accounting-qbo-worksheets.mjs';

const PREFIX = 'merchant_accounting_maintenance_';
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const SHA = /^[a-f0-9]{64}$/;
const ACTIVE = new Set(['QUEUED', 'RUNNING']);
const TERMINAL = new Set(['COMPLETE', 'FAILED', 'CANCELLED', 'INTERRUPTED']);
const FIELDS = {
  pause: [], review: [], resume: [],
  backup: ['expectedReviewId', 'externalWritersStopped', 'label'],
  verify: ['backupId', 'expectedSha256'],
  restore: ['backupId', 'expectedSha256', 'externalWritersStopped', 'relocate', 'expectedWorkspaceId', 'expectedSourcesSha256'],
  cancel: ['jobId'],
};
const FILE_FIELDS = [...qboWorksheetFileSelectors, 'kind', 'changeId', 'recoveryId', 'runId', 'exportId', 'collectionId', 'sourceId',
  'reviewId', 'closeId', 'handoffId', 'revisionId', 'adjustmentId', 'jobId', 'planId', 'responseId', 'nativePost', 'attemptId', 'file', 'statementId', 'customerId', 'usageId', 'usageOpeningId', 'replacesId', 'from', 'until', 'profileId', 'captureId', 'returnId', 'rollbackId', 'scope', 'cycleId', 'fileId', 'receivedId', 'clientId', 'documentId', 'invoiceId', 'paymentRequestId', 'refundId', 'bankImportId', 'batchId', 'asOf'];
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (code, message) => Object.assign(new Error(message), { code: 'ACCOUNTING_MAINTENANCE_CLIENT_' + code });
function exact(value, fields) {
  if (!plain(value) || Object.keys(value).some(key => !fields.includes(key)))
    throw fail('ARGUMENTS', 'Use only the declared fields for this operation.');
}
function identifier(value, expression, name) {
  if (typeof value !== 'string' || !expression.test(value)) throw fail('ARGUMENTS', 'Supply the exact ' + name + '.');
  return value;
}
function number(value, minimum, maximum, name) {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum)
    throw fail('ARGUMENTS', name + ' must be an integer from ' + minimum + ' to ' + maximum + '.');
  return value;
}
function workspaceAlias(value) { return identifier(value, /^[a-z0-9][a-z0-9_-]{0,63}$/, 'configured workspace alias'); }

/** Validate the exact request before retaining or submitting it. No ID is generated here. */
export function accountingMaintenanceArguments(kind, value) {
  if (!Object.hasOwn(FIELDS, kind)) throw fail('ARGUMENTS', 'Choose pause, review, backup, verify, restore, resume or cancel.');
  exact(value, ['actor', 'requestId', ...FIELDS[kind]]);
  if (typeof value.actor !== 'string' || !value.actor.trim() || value.actor.trim().length > 160)
    throw fail('ARGUMENTS', 'Supply the responsible actor, from 1 to 160 characters.');
  const args = { actor: value.actor.trim(), requestId: identifier(value.requestId, UUID, 'retained request UUID') };
  if (kind === 'restore' && (value.expectedWorkspaceId !== undefined || value.expectedSourcesSha256 !== undefined)) {
    identifier(value.expectedWorkspaceId, SHA, 'original workspace identity SHA256');
    identifier(value.expectedSourcesSha256, SHA, 'original source identity SHA256');
  }
  for (const field of FIELDS[kind]) {
    if (['label', 'relocate', 'expectedWorkspaceId', 'expectedSourcesSha256'].includes(field) && value[field] === undefined) continue;
    if (field === 'relocate') {
      if (typeof value[field] !== 'boolean') throw fail('ARGUMENTS', 'Use an explicit boolean relocate choice.');
      args[field] = value[field];
    } else if (field === 'expectedReviewId' || field === 'expectedSha256' || field === 'expectedWorkspaceId' || field === 'expectedSourcesSha256') args[field] = identifier(value[field], SHA, field + ' SHA256');
    else if (field === 'jobId') args[field] = identifier(value[field], UUID, 'original job UUID');
    else if (field === 'externalWritersStopped') {
      if (value[field] !== true) throw fail('ARGUMENTS', 'Confirm externalWritersStopped:true after stopping source writers outside this MCP session.');
      args[field] = true;
    } else if (field === 'backupId') {
      args[field] = identifier(value[field], /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/, 'retained backup ID');
      if (value[field] === 'operations') throw fail('ARGUMENTS', 'Choose an original backup catalog ID.');
    } else {
      if (typeof value[field] !== 'string' || !value[field].trim() || value[field].trim().length > 160)
        throw fail('ARGUMENTS', 'Use a backup label from 1 to 160 characters.');
      args[field] = value[field].trim();
    }
  }
  return args;
}

/** Reuse an already initialized stdio, in-process or HTTP merchant connection. */
export function createAccountingMaintenanceClient({ workspace, call } = {}) {
  workspaceAlias(workspace);
  if (typeof call !== 'function') throw fail('ARGUMENTS', 'Supply the existing MCP structured-result call(name, arguments, options).');
  const ownedReads = new Set(), fileCalls = new Set();
  let drainingReaders = false;
  async function invoke(name, args = {}, options) {
    const result = await call(name, { ...args, workspace }, options);
    if (!plain(result)) throw fail('REPLY', 'The merchant tool returned no structured result.');
    return result;
  }
  function checkedJob(result, jobId) {
    if (!plain(result.job) || result.job.id !== jobId || result.job.requestId !== jobId ||
        !ACTIVE.has(result.job.status) && !TERMINAL.has(result.job.status))
      throw fail('REPLY', 'The merchant reply does not identify the original retained job and status.');
    return result;
  }
  function readOriginal(args, options) {
    if (drainingReaders) throw fail('READ_DRAINING', 'Finish the current reader drain before opening another original read.');
    const pending = invoke('merchant_accounting_file', args, options).then(result => {
      if (UUID.test(result.readId ?? '') && result.nextOffset !== null) ownedReads.add(result.readId);
      return result;
    });
    fileCalls.add(pending); pending.then(() => fileCalls.delete(pending), () => fileCalls.delete(pending));
    return pending;
  }
  async function drainThen(operation) {
    if (drainingReaders) throw fail('READ_DRAINING', 'A reader drain is already active on this client.');
    drainingReaders = true;
    try {
      await Promise.allSettled([...fileCalls]);
      for (const readId of [...ownedReads]) await client.releaseFile(readId, { timeoutMs: 10000 });
      return operation ? await operation() : { workspace, released: true, activeFileReads: ownedReads.size };
    } finally { drainingReaders = false; }
  }
  const client = {
    workspace,
    open: options => invoke('merchant_accounting_open', {}, options),
    closeWorkspace: options => drainThen(() => invoke('merchant_accounting_close', {}, options)),
    registerFileRead(readId) {
      identifier(readId, UUID, 'owned file-read UUID');
      if (drainingReaders) throw fail('READ_DRAINING', 'Register an already-owned read before the reader drain begins.');
      ownedReads.add(readId); return { workspace, readId };
    },
    drainFileReads: () => drainThen(),
    async status(args = {}, options) {
      exact(args, ['view', 'offset', 'limit']);
      if (args.view !== undefined && !['summary', 'backups', 'jobs', 'sources'].includes(args.view)) throw fail('ARGUMENTS', 'Choose summary, backups, jobs or sources.');
      if (args.offset !== undefined) number(args.offset, 0, Number.MAX_SAFE_INTEGER, 'offset');
      if (args.limit !== undefined) number(args.limit, 1, 200, 'limit');
      return invoke(PREFIX + 'status', args, options);
    },
    async command(kind, value, options) {
      const args = accountingMaintenanceArguments(kind, value);
      const submit = () => invoke(PREFIX + kind, args, options);
      const result = checkedJob(await (kind === 'pause' ? drainThen(submit) : submit()), args.requestId);
      if (result.accepted !== true) throw fail('REPLY', 'The merchant did not acknowledge this retained operation.');
      return result;
    },
    async job(jobId, options) {
      identifier(jobId, UUID, 'original job UUID');
      return checkedJob(await invoke(PREFIX + 'job', { jobId }, options), jobId);
    },
    /** Poll only the retained job. A timeout or failed job never starts another operation. */
    async wait(jobId, { maxWaitMs = 30000, pollMs = 500, signal } = {}) {
      number(maxWaitMs, 0, 86400000, 'maxWaitMs'); number(pollMs, 100, 60000, 'pollMs');
      const until = Date.now() + maxWaitMs;
      for (;;) {
        signal?.throwIfAborted();
        const result = await client.job(jobId, { requestSignal: signal });
        const pending = ACTIVE.has(result.job.status);
        if (!pending || Date.now() >= until) return { ...result, pending };
        await delay(Math.min(pollMs, until - Date.now()), undefined, { signal });
      }
    },
    async releaseFile(readId, options) {
      identifier(readId, UUID, 'owned file-read UUID');
      const result = await invoke('merchant_accounting_file_release', { readId }, options);
      ownedReads.delete(readId); return result;
    },
    /** Consume one original file, retaining its selectors and SHA on every chunk. */
    async *fileChunks(selection, { expectedSha256, chunkBytes = 65536, signal } = {}) {
      exact(selection, FILE_FIELDS);
      if (!['response', 'report', 'export', 'collection', 'pricing', 'period', 'accountant', 'adjustment', 'qbo', 'xero', 'qbo-source-change', 'xero-source-change', 'qbo-worksheet', 'customer-statement', 'customer-statement-preview', 'customer-usage-period-preview', 'cryptoworth', 'runbooks', 'portfolio', 'buyer-source', 'receivables-document', 'receivables-quote', 'receivables-preview', 'receivables-payment', 'receivables-refund', 'receivables-bank', 'receivables-remittance', 'receivables-customer'].includes(selection.kind))
        throw fail('ARGUMENTS', 'Choose an original accounting file kind.');
      if (expectedSha256 !== undefined) identifier(expectedSha256, SHA, 'original file SHA256');
      number(chunkBytes, 1, 196608, 'chunkBytes');
      const selectors = structuredClone(selection), hash = createHash('sha256');
      let readId, file, offset = 0, complete = false, problem;
      try {
        for (;;) {
          signal?.throwIfAborted();
          if (readId && !ownedReads.has(readId)) throw fail('READ_RELEASED', 'This client drained the unfinished read. Open a new read with its original selectors and SHA256.');
          const chunk = await readOriginal({ ...selectors, offset, limit: chunkBytes,
            ...(readId ? { readId } : {}), ...(expectedSha256 ? { expectedSha256 } : {}) }, { requestSignal: signal });
          identifier(chunk.readId, UUID, 'owned file-read UUID');
          // Retain the observed handle even if a malformed reply needs cleanup.
          if (!readId) readId = chunk.readId;
          if (chunk.nextOffset !== null) ownedReads.add(readId);
          if (chunk.readId !== readId || !plain(chunk.file) || !SHA.test(chunk.file.sha256 ?? '') ||
              !Number.isSafeInteger(chunk.file.bytes) || chunk.file.bytes < 0 || chunk.offset !== offset ||
              chunk.encoding !== 'base64' || typeof chunk.data !== 'string') throw fail('FILE_REPLY', 'The original file chunk has inconsistent metadata.');
          if (!file) { file = chunk.file; expectedSha256 ??= file.sha256; }
          if (chunk.file.sha256 !== expectedSha256 || chunk.file.bytes !== file.bytes || chunk.file.name !== file.name)
            throw fail('FILE_CHANGED', 'The retained file identity changed during this read.');
          const bytes = Buffer.from(chunk.data, 'base64');
          const next = offset + bytes.length;
          if (bytes.toString('base64') !== chunk.data || bytes.length !== chunk.bytesRead || bytes.length > chunkBytes ||
              next > file.bytes || (next < file.bytes ? chunk.nextOffset !== next || !bytes.length : chunk.nextOffset !== null))
            throw fail('FILE_REPLY', 'The original file chunk has inconsistent bytes or offsets.');
          hash.update(bytes); offset = next; complete = chunk.nextOffset === null;
          if (complete) ownedReads.delete(readId);
          if (complete && hash.digest('hex') !== expectedSha256) throw fail('FILE_CHANGED', 'The complete original file differs from its SHA256.');
          yield { ...chunk, bytes, complete };
          if (complete) return;
        }
      } catch (error) { problem = error; throw error; }
      finally {
        // The host releases an EOF snapshot itself. A partial read belongs to this caller.
        if (readId && !complete && ownedReads.has(readId)) {
          try { await client.releaseFile(readId, { timeoutMs: 10000 }); }
          catch (error) { if (problem) problem.releaseError = { code: error.code, message: error.message }; else throw error; }
        }
      }
    },
  };
  return Object.freeze(client);
}

/** Connect to the existing merchant HTTP listener; never starts a second host. */
export async function connectAccountingMaintenanceClient({ workspace, ...options } = {}) {
  workspaceAlias(workspace);
  const connection = await openMerchantFileClient({ ...options, errorPrefix: 'ACCOUNTING_MAINTENANCE',
    clientName: 'starforge-accounting-maintenance' });
  return Object.freeze({ ...createAccountingMaintenanceClient({ workspace, call: connection.call }), endpoint: connection.endpoint });
}

#!/usr/bin/env node
// MIT. Prepared buyer startup and customer operations for original accounting controllers.
import { constants } from 'node:fs';
import { open, mkdir, lstat, realpath, rename, unlink, link } from 'node:fs/promises';
import { createHash, randomUUID } from 'node:crypto';
import { resolve, join, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';
import { acquireStateLease } from '../../stellar/scf-starforge-20261009/merchant-fleet-gateway/state-lease.mjs';
import { writePrivate, privateSupportDirectory } from './host-files.mjs';
import { accountingPlatformOperation, accountingPlatformActions, connectAccountingPlatformClient } from './accounting-platform-client.mjs';
import { downloadAccountingMaintenanceFile } from './accounting-maintenance-cli.mjs';
import { qboWorksheetFileSelection } from './accounting-qbo-worksheets-client.mjs';

const REQUEST = 'stellar-forge.accounting-platform-client-request.v1';
const STATE = 'stellar-forge.accounting-platform-client-state.v1';
const sha = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const now = () => new Date().toISOString();
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (code, message) => Object.assign(new Error(message), { code: 'ACCOUNTING_PLATFORM_CLIENT_' + code });
const problem = error => ({ code: error.code ?? 'ERROR', message: String(error.message).slice(0, 2000) });
function need(ok, message, code = 'ARGUMENTS') { if (!ok) throw fail(code, message); }
function endpoint(url) {
  let result; try { result = new URL(url); } catch { throw fail('CONFIGURATION', 'Supply the original HTTPS or loopback HTTP merchant endpoint.'); }
  need(!result.username && !result.password && !result.search && !result.hash &&
    (result.protocol === 'https:' || result.protocol === 'http:' && ['127.0.0.1', '[::1]'].includes(result.hostname)),
    'Use an original HTTPS or loopback HTTP endpoint without embedded credentials, query or fragment.', 'CONFIGURATION');
  return result.href;
}
async function privateDirectory(value) {
  const path = resolve(value); await privateSupportDirectory(path); const info = await lstat(path);
  need(await realpath(path) === path && (!process.getuid || info.uid === process.getuid()),
    'Use a private owner-controlled directory without symlink ancestors.', 'PRIVATE_DIRECTORY');
  return path;
}
async function readJson(path, maximum = 2 * 1024 * 1024) {
  const handle = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0));
  try {
    const info = await handle.stat();
    need(info.isFile() && info.nlink === 1 && info.size <= maximum && !(info.mode & 0o077) &&
      (!process.getuid || info.uid === process.getuid()), 'Use the original bounded private regular JSON file.', 'PRIVATE_FILE');
    const bytes = await handle.readFile(); need(bytes.length <= maximum, 'The original file grew beyond its supported size.', 'PRIVATE_FILE');
    return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
  } finally { await handle.close(); }
}
async function syncDirectory(path) { const handle = await open(path, constants.O_RDONLY); try { await handle.sync(); } finally { await handle.close(); } }
function validateRequest(request) {
  const fields = ['schema', 'preparedAt', 'url', 'workspace', 'platform', 'tokenEnv', 'operation', 'preview', 'sha256'];
  need(plain(request) && Object.keys(request).length === fields.length && fields.every(field => Object.hasOwn(request, field)),
